inline Walker::Walker()
    : pos(Coord(1, 1)),
      frames(std::vector<Frame>{Frame(Coord(3, 4)), Frame(Coord(5, 6))}) {}

// # method: return of a rebound local
// def stepped(self, d: int32) -> Coord:
//     c = self.pos
//     c = Coord(c.column + d, c.row)
//     return c  # tpyc: ok
inline Coord Walker::stepped(int32_t d) const {
    Coord c = this->pos;
    c = Coord((::tpy::add_check<int32_t>(c.column, d)), c.row);
    return c;
}

// # method: return of a plain field
// def at(self) -> Coord:
//     return self.pos  # tpyc: ok
inline Coord Walker::at() const {
    return this->pos;
}

