struct CalmTree {
    using variant_type = ::tpy::Union<Calm, std::vector<CalmTree>>;
    variant_type value;

    CalmTree() = default;
    template<typename T>
        requires std::constructible_from<variant_type, T&&>
    CalmTree(T&& v) : value(std::forward<T>(v)) {}

    bool operator==(const CalmTree&) const = default;

    friend std::ostream& operator<<(std::ostream& os, const CalmTree& v) {
        ::tpy::detail::print_element(os, v.value);
        return os;
    }
};

